let hasZero = false, zeroValue = 0;

function slotOf(key) {
    return Math.imul(key, 0x9E3779B9) >>> shift;
}

function insert(key, value) {
    if (key === 0) { hasZero = true; zeroValue = value; return; }
    let i = slotOf(key);
    while (table[2 * i] !== 0 && table[2 * i] !== key) i = (i + 1) & mask;
    table[2 * i] = key;
    table[2 * i + 1] = value;
}

