// analytics — filter → map → group-by → reduce over N LCG-generated records.
// Reads N from process.argv[2]; prints two lines (kept count, checksum),
// byte-identical across every language. Every value is an exact integer Number:
// the LCG step keeps only the low 31 bits of seed*1103515245+12345, which
// Math.imul and >>> 0 compute exactly mod 2^32; key and value are below 2^15, so
// value*key+7 < 2^31, and every group total stays below 2*MOD < 2^31.
'use strict';

const MOD = 1000000007;
const NGROUP = 32768;

function main() {
  const n = parseInt(process.argv[2], 10);
  let seed = 42;
  const groups = [];
  for (let g = 0; g < NGROUP; g++) groups.push(0);
  let kept = 0;
  for (let r = 0; r < n; r++) {
    seed = ((Math.imul(seed, 1103515245) + 12345) >>> 0) % 2147483648;
    const key = (seed >> 16) & 0x7fff;
    seed = ((Math.imul(seed, 1103515245) + 12345) >>> 0) % 2147483648;
    const value = (seed >> 16) & 0x7fff;
    if (value % 3 === 0) continue;
    const mapped = (value * key + 7) % MOD;
    const g = key % NGROUP;
    groups[g] = (groups[g] + mapped) % MOD;
    kept++;
  }
  let checksum = 0;
  for (let g = 0; g < NGROUP; g++) {
    checksum = (checksum * 31 + groups[g]) & 268435455;
  }
  process.stdout.write(`${kept}\n${checksum}\n`);
}

main();

"use strict";

const MOD = 1000000007;
const NREG = 8;

// Every register stays in [0, MOD) and MOD < 2^30, so every result is an exact integer Number except the MULADD
// product, which reaches 2^60. It splits b = bh*2^15 + bl with bh, bl < 2^15: a*bh, (a*bh % MOD)*2^15 and a*bl are each
// below 2^45, so the sum stays below 2^47 and every step is exact.
function mulAddMod(a, b) {
    return ((a * (b >>> 15)) % MOD * 32768 + a * (b & 32767) + 1) % MOD;
}

function main() {
    const n = Number(process.argv[2]);
    let seed = 42;
    const regs = [];
    for (let i = 0; i < NREG; i++) regs.push(i + 1);
    for (let k = 0; k < n; k++) {
        seed = ((Math.imul(seed, 1103515245) + 12345) >>> 0) % 2147483648;
        const instr = (seed >> 8) & 0x7fffff;
        const op = instr % 8;
        const dst = Math.floor(instr / 8) % NREG;
        const a = Math.floor(instr / 64) % NREG;
        const imm = Math.floor(instr / 512) % 251;
        switch (op) {
            case 0: regs[dst] = imm; break;
            case 1: regs[dst] = (regs[dst] + regs[a]) % MOD; break;
            case 2: regs[dst] = (regs[dst] + MOD - regs[a]) % MOD; break;
            case 3: regs[dst] = mulAddMod(regs[dst], regs[a]); break;
            case 4: regs[dst] = (regs[dst] + imm) % MOD; break;
            case 5: regs[dst] = (regs[dst] * (imm + 1)) % MOD; break;
            case 6: regs[dst] = regs[a]; break;
            case 7: regs[dst] = (regs[dst] + regs[a] + imm) % MOD; break;
        }
    }
    let checksum = 0;
    for (let i = 0; i < NREG; i++) {
        checksum = (checksum * 31 + regs[i]) & 268435455;
    }
    console.log(checksum.toString());
}

main();

// sha256 — an iterated SHA-256 hash chain: H^N(0), hand-rolled (NO crypto module, so
// NO SHA-NI hardware path). 32-byte state = 8 big-endian u32 words; output is the 8
// digest words as unsigned 32-bit decimals. Words are held as int32 in Int32Arrays and
// every add is wrapped with `| 0`, as Java's int wraps; `>>> 0` reads them unsigned for output.
'use strict';

const K = new Int32Array([
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

const H = new Int32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
const W = new Int32Array(64);

function rotr(x, n) {
    return (x >>> n) | (x << (32 - n));
}

// SHA-256 of a 32-byte message given as 8 big-endian u32 words -> 8-word digest.
function sha256Words(inw, out) {
    const h = H;
    const w = W;
    for (let i = 0; i < 8; i++) w[i] = inw[i];
    w[8] = 0x80000000;                            // the 0x80 pad byte after 32 bytes
    for (let i = 9; i < 15; i++) w[i] = 0;
    w[15] = 256;                                  // message length in bits
    for (let i = 16; i < 64; i++) {
        const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
        const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
        w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
    }
    let a = h[0], b = h[1], c = h[2], d = h[3], e = h[4], f = h[5], g = h[6], hh = h[7];
    for (let i = 0; i < 64; i++) {
        const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
        const ch = (e & f) ^ (~e & g);
        const t1 = (hh + S1 + ch + K[i] + w[i]) | 0;
        const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
        const maj = (a & b) ^ (a & c) ^ (b & c);
        const t2 = (S0 + maj) | 0;
        hh = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    out[0] = (h[0] + a) | 0; out[1] = (h[1] + b) | 0; out[2] = (h[2] + c) | 0; out[3] = (h[3] + d) | 0;
    out[4] = (h[4] + e) | 0; out[5] = (h[5] + f) | 0; out[6] = (h[6] + g) | 0; out[7] = (h[7] + hh) | 0;
}

function main() {
    if (process.argv.length < 3) {
        process.stderr.write('usage: sha256 <n>\n');
        process.exit(1);
    }
    const n = Number(process.argv[2]);
    const state = new Int32Array(8);
    const next = new Int32Array(8);
    for (let k = 0; k < n; k++) {
        sha256Words(state, next);
        for (let i = 0; i < 8; i++) state[i] = next[i];
    }
    let out = '';
    for (let i = 0; i < 8; i++) {
        out += (state[i] >>> 0) + '\n';
    }
    process.stdout.write(out);
}

main();
